// tests/aggregation.test.js — the JS port against the Python golden file.
//
// golden.json is generated by generate_golden.py from the real Python
// implementation. If these tests fail, the JavaScript has drifted from
// Python — fix the port, never the golden file (regenerating it is only
// legitimate when the Python semantics themselves changed).
const test = require("node:test");
const assert = require("node:assert");
const path = require("node:path");

const models = require("../core/models.js");
const agg = require("../core/aggregation.js");
const golden = require("./golden.json");

function build(casemanifest) {
  const prices = models.coercePrices(golden.prices);
  return agg.buildDailyUsage({ tokenTrend: casemanifest.trend }, casemanifest.today, prices);
}

test("每日聚合与 Python 实现逐字段一致（黄金对照）", () => {
  for (const [name, casemanifest] of Object.entries(golden.cases)) {
    const js = build(casemanifest);
    assert.deepStrictEqual(js, casemanifest.result, `case ${name} drifted from Python`);
  }
});

test("当日有真实用量：三模型合计与分类费用", () => {
  const r = build(golden.cases.normal_day);
  assert.strictEqual(r.totalTokens, 41_000_000 + 11_852_000 + 2_180_000 + 340_000 + 12_000);
  // TOKEN 行按 tokens/1e6*blendedPrice 计价。
  const glm = r.models.find((m) => m.requestType === "glm-5.3-flash");
  assert.strictEqual(glm.cost, (41_000_000 / 1e6) * 2.24);
});

test("FLAT 模型保留 Token、费用为 null（包月不计入当日）", () => {
  const trae = build(golden.cases.normal_day).models.find(
    (m) => m.requestType === "trae-subscription"
  );
  assert.strictEqual(trae.tokens, 340_000);
  assert.strictEqual(trae.cost, null);
  assert.strictEqual(trae.monthlyFee, 49.0);
});

test("部分模型价格未知：总额 null，绝不冒充全部费用", () => {
  const r = build(golden.cases.partial_price_unknown);
  assert.strictEqual(r.totalCost, null);
  const unpriced = r.models.find((m) => m.requestType === "unpriced-token");
  assert.strictEqual(unpriced.cost, null);
  const unknown = r.models.find((m) => m.requestType === "unknown-model-xyz");
  assert.strictEqual(unknown.cost, null);
  assert.strictEqual(unknown.billType, "UNKNOWN");
});

test("空响应聚合为 0.0（Python 空集语义），不是 null", () => {
  const r = build(golden.cases.empty_trend);
  assert.strictEqual(r.totalTokens, 0);
  assert.strictEqual(r.totalCost, 0.0);
});

test("昨日数据被日期过滤，不进入今日聚合", () => {
  const r = build(golden.cases.normal_day);
  assert.strictEqual(r.totalTokens, 55_384_000); // 不含 999,999,999 的昨日行
});

test("百亿级单日不丢精度", () => {
  const r = build(golden.cases.huge_day);
  assert.strictEqual(r.totalTokens, 10_299_999_999);
  assert.strictEqual(r.models[0].cost, (10_299_999_999 / 1e6) * 2.24);
});
